import XCTest
import Foundation
import PhotoCraftCore
@testable import PhotoCraftImaging

final class PixelFillStrokeIOTests:XCTestCase{
  func testNewStrokesRemainEditableAndAllStoredBinarySamplesSurvivePSDPSBAndNative()throws{
    for depth in PixelDepth.allCases{for format:PSDFileFormat in [.psd,.psb]{var d=try CraftDocument(width:12,height:10,depth:depth);d.layers[0].content = .raster(try Surface(width:12,height:10,depth:depth));d.selection = .init(x:3,y:3,width:5,height:4);var settings=PixelPaintSettings(color:.white);settings.width=2;settings.location = .outside;try Command.pixelPaint(.init(.stroke,target:.layer(d.layers[0].id),settings:settings)).apply(to:&d);let bytes=try PSDCodec.writeRasterLayers(d,format:format),read=try PSDCodec.read(bytes);XCTAssertEqual(read.depth,depth);XCTAssertEqual(read.layers.count,1);XCTAssertNil(read.layers[0].smartObject);guard case .raster(let original)=d.layers[0].content,case .raster(let output)=read.layers[0].content else{return XCTFail()};XCTAssertEqual(output.width,original.width);XCTAssertEqual(output.height,original.height);for y in 0..<10{for x in 0..<12{XCTAssertTrue(output.pixel(x:x,y:y).hasSameBits(as:original.pixel(x:x,y:y)))}};XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(d)),d)}}
  }
  func testSpotDisplayPaintRetainsUneditedOriginalGrayWordsAndSharedAtomicSerializer()throws{
    var d=try CraftDocument(width:12,height:10,depth:.f32);let gray=try Surface(width:12,height:10,depth:.f32,fill:Pixel(0.7,0.7,0.7)),density=try Surface(width:12,height:10,depth:.f32,fill:Pixel(0.3,0.3,0.3));var channel=AlphaChannel(name:"Spot",pixels:density,spot:.init(color:Pixel(0.1,0.4,0.6)));channel.psdSpotGray=gray;d.alphaChannels=[channel];d.selection = .init(x:3,y:3,width:5,height:4);try Command.pixelPaint(.init(.fill,target:.channel(.alpha(channel.id)),settings:.init(color:Pixel(0.2,0.2,0.2)))).apply(to:&d);let output=try XCTUnwrap(d.alphaChannels?.first);XCTAssertTrue(try XCTUnwrap(output.psdSpotGray).pixel(x:0,y:0).hasSameBits(as:gray.pixel(x:0,y:0)));XCTAssertEqual(output.pixels.pixel(x:4,y:4).r,1-Float(0.2));XCTAssertEqual(try XCTUnwrap(output.psdSpotGray).pixel(x:4,y:4).r,Float(0.2));XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(d)),d)
    let directory=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true);defer{try? FileManager.default.removeItem(at:directory)};for format:PSDFileFormat in [.psd,.psb]{let url=directory.appendingPathComponent("paint."+(format == .psd ? "psd":"psb"));let bytes=try PSDCodec.writeRasterLayers(d,format:format);try PSDCodec.writeRasterLayers(d,to:url,format:format);XCTAssertEqual(try Data(contentsOf:url),bytes);let read=try PSDCodec.read(bytes);XCTAssertEqual(read.alphaChannels?.first?.name,"Spot");XCTAssertTrue(try XCTUnwrap(read.alphaChannels?.first?.psdSpotGray).pixel(x:0,y:0).hasSameBits(as:gray.pixel(x:0,y:0)))}
  }
}
